// Smoke harness for the standalone index.html artifact.
// Exercises the exact embedded <script> through init + rAF frames
// with a minimal dependency-free DOM + 2D-canvas stub.
const fs = require("fs");
const path = "<WORKSPACE>/meta/muse-spark-1.3/high/index.html";
const html = fs.readFileSync(path, "utf8");

const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]);
if (scripts.length !== 1) throw new Error("expected exactly 1 inline script, got " + scripts.length);
const js = scripts[0];
if (/https?:\/\//.test(js)) throw new Error("external URL inside script");

// --- minimal DOM stub ---
function makeCtx() {
  return {
    clearRect() {}, beginPath() {}, arc() {}, fill() {},
    createRadialGradient() { return { addColorStop() {} }; },
    set fillStyle(v) {}, get fillStyle() { return ""; },
  };
}
function makeEl(id) {
  const el = {
    id, style: { setProperty() {} },
    children: [],
    appendChild(c) { this.children.push(c); return c; },
    addEventListener() {},
    getBoundingClientRect: () => ({ left: 0, top: 0, width: 1280, height: 800 }),
    getContext: () => makeCtx(),
  };
  return el;
}
const sesameBox = makeEl("sesame");
const elements = {
  stage: makeEl("stage"), tilt: makeEl("tilt"), halo: makeEl("halo"),
  steam: makeEl("steam"), "glow-dust": makeEl("glow-dust"), sesame: sesameBox,
  broth: makeEl("broth"),
};
let created = 0;
const rafQueue = [];
global.document = {
  getElementById: (id) => elements[id] || null,
  createElement: () => { created++; return makeEl("dyn" + created); },
  body: { style: { setProperty() {} } },
};
global.window = global;
global.matchMedia = () => ({ matches: false });
global.performance = { now: () => 1000 };
global.requestAnimationFrame = (cb) => { rafQueue.push(cb); return rafQueue.length; };
global.addEventListener = undefined; // must exist on window
global.window.addEventListener = () => {};

// run exact artifact script
eval(js);

// init assertions
if (sesameBox.children.length !== 12) throw new Error("sesame seeds: " + sesameBox.children.length);
if (rafQueue.length !== 1) throw new Error("rAF not queued at init");

// pump 5 frames incl. a synthetic mousemove-driven state
for (let f = 0; f < 5; f++) {
  const q = rafQueue.splice(0);
  q.forEach(cb => cb(1000 + f * 16));
}
if (typeof elements.tilt.style.transform === "undefined") throw new Error("no tilt transform");
console.log("SMOKE PASS: init ok, 12 sesame seeds, 5 rAF frames rendered, tilt=" +
  JSON.stringify(elements.tilt.style.transform).slice(0, 80));

// reduced-motion path: re-run with matchMedia true, expect no rAF loop
Object.keys(elements).forEach(k => { elements[k].children = []; });
rafQueue.length = 0;
sesameBox.children = [];
global.matchMedia = () => ({ matches: true });
eval(js);
if (sesameBox.children.length !== 12) throw new Error("RM: sesame seeds " + sesameBox.children.length);
if (rafQueue.length !== 0) throw new Error("RM: rAF loop should not run");
console.log("SMOKE PASS: prefers-reduced-motion renders single static frame, no loop");
